// median-tests | median / sorting-and-assertions | single / p3
// Documented reference implementation.

import { test } from "node:test";
import assert from "node:assert/strict";

function median_doc(values: readonly number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1
    ? sorted[middle]
    : (sorted[middle - 1] + sorted[middle]) / 2;
}

test("median handles odd input", () => {
  assert.equal(median_doc([11]), 11);
});

test("median handles empty input", () => {
  assert.equal(median_doc([]), 0);
});

test("median keeps duplicate values", () => {
  assert.equal(median_doc([12, 12, 11, 11]), 11.5);
});

// generic-stack | stack-operations / array-backed | negative / p2

class Stack<T> {
  private readonly items: T[] = [];

  push(value: T): void {
    this.items.push(value);
  }

  pop(): T {
    const value = this.items.pop();
    if (value === undefined) throw new Error("stack is empty");
    return value;
  }

  peek(): T | undefined {
    return this.items[this.items.length - 1];
  }

  get size(): number {
    return this.items.length;
  }
}

const stack = new Stack<number>();
stack.push(-10);
stack.push(-2);
stack.push(0);
stack.push(10);
stack.push(11);
console.log(stack.size, stack.peek(), stack.pop());

