// memoize | memoization / map-cache | single / p3

function memoize<A extends string | number, R>(compute: (arg: A) => R): (arg: A) => R {
  const cache = new Map<A, R>();
  return (arg: A): R => {
    const cached = cache.get(arg);
    if (cached !== undefined) return cached;
    const value = compute(arg);
    cache.set(arg, value);
    return value;
  };
}

