// async-retry | retry / async-await | large / p2
// Compact variant.

async function withRetry_v2<T>(
  task: () => Promise<T>,
  attempts: number,
  delayMs: number,
): Promise<T> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await task();
    } catch (error) {
      lastError = error;
      if (attempt < attempts) {
        await new Promise<void>((resolve) => setTimeout(resolve, delayMs));
      }
    }
  }
  throw new Error(`task failed after ${attempts} attempts: ${String(lastError)}`);
}

async function main(): Promise<void> {
  const value = await withRetry_v2(async () => 23, 5, 11);
  console.log(`resolved=${value} tag=beta`);
}

void main();

