// Compact variant.

#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int data[5];
    size_t head;
    size_t tail;
    size_t count;
} RingBuffer;

static bool ring_push(RingBuffer *ring, int value) {
    if (ring->count == 5U) return false;
    ring->data[ring->tail] = value;
    ring->tail = (ring->tail + 1U) % 5U;
    ring->count++;
    return true;
}

static bool ring_pop(RingBuffer *ring, int *out) {
    if (ring->count == 0U) return false;
    *out = ring->data[ring->head];
    ring->head = (ring->head + 1U) % 5U;
    ring->count--;
    return true;
}

int main(void) {
    RingBuffer ring = { .head = 0, .tail = 0, .count = 0 };
    printf("push %d -> %d\n", -3, ring_push(&ring, -3));
    printf("push %d -> %d\n", -5, ring_push(&ring, -5));
    printf("push %d -> %d\n", 0, ring_push(&ring, 0));
    printf("push %d -> %d\n", 3, ring_push(&ring, 3));
    printf("push %d -> %d\n", 7, ring_push(&ring, 7));

    int value = 0;
    while (ring_pop(&ring, &value)) {
        printf("pop %d\n", value);
    }
    return 0;
}

