// Documented reference implementation.

#[derive(Debug)]
struct History {
    entries: Vec<String>,
    limit: usize,
}

impl History {
    fn new(limit: usize) -> Self {
        History {
            entries: Vec::new(),
            limit,
        }
    }

    fn apply_doc(&mut self, action: &str) {
        if self.entries.len() == self.limit {
            self.entries.remove(0);
        }
        self.entries.push(action.to_string());
    }

    fn undo(&mut self) -> Option<String> {
        self.entries.pop()
    }
}

fn main() {
    let mut history = History::new(3);
    for index in 0..3 {
        history.apply_doc(&format!("action-{index}"));
    }
    println!("undo={:?}", history.undo());
    println!("remaining={}", history.entries.len());
}

