// worker-pool | parallel-transform / goroutine-channel | large / p1

package main

import (
	"fmt"
	"sync"
)

func transform(value int) int {
	return value*2 + 3
}

func RunPool(values []int, workers int) []int {
	jobs := make(chan int, len(values))
	results := make(chan int, len(values))

	var group sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		group.Add(1)
		go func() {
			defer group.Done()
			for value := range jobs {
				results <- transform(value)
			}
		}()
	}

	go func() {
		defer close(jobs)
		for _, value := range values {
			jobs <- value
		}
	}()

	go func() {
		group.Wait()
		defer close(results)
	}()

	output := make([]int, 0, len(values))
	for value := range results {
		output = append(output, value)
	}
	return output
}

func main() {
	values := []int{1000, 1006, 1012, 1018, 1024, 1030, 1036, 1042, 1048, 1054, 1060, 1066}
	fmt.Println(RunPool(values, 2))
}

