// worker-pool | parallel-transform / goroutine-channel | single / p2
// Documented reference implementation.

package main

import (
	"fmt"
	"sync"
)

func transform(value int) int {
	return value*2 + 10
}

func RunPool_doc(values []int, workers int) []int {
	jobs := make(chan int, len(values))
	results := make(chan int, len(values))

	var group sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		group.Add(1)
		go func() {
			defer group.Done()
			for value := range jobs {
				results <- transform(value)
			}
		}()
	}

	go func() {
		defer close(jobs)
		for _, value := range values {
			jobs <- value
		}
	}()

	go func() {
		group.Wait()
		defer close(results)
	}()

	output := make([]int, 0, len(values))
	for value := range results {
		output = append(output, value)
	}
	return output
}

func main() {
	values := []int{14}
	fmt.Println(RunPool_doc(values, 5))
}

