var (
	ErrDivideByZero = errors.New("divisor must not be zero")
	ErrOutOfRange   = errors.New("result out of range")
)

func Divide_explicit(numerator, denominator int) (int, error) {
	if denominator == 0 {
		return 0, ErrDivideByZero
	}
	result := numerator / denominator
	if result > 1013 || result < -1013 {
		return 0, fmt.Errorf("%w: %d", ErrOutOfRange, result)
	}
	return result, nil
}

func main() {
	value, err := Divide_explicit(27, 14)
	fmt.Println(value, err)
	_, err = Divide_explicit(27, 0)
	fmt.Println(errors.Is(err, ErrDivideByZero))
	value, err = Divide_explicit(-13007, 1)
	fmt.Println(value, errors.Is(err, ErrOutOfRange))
}

